SNTools.onRouteChange(async () => {
  const record = SNTools.getRecord();
  if (!record || record.table !== 'incident' || record.isWorkspace) return;

  // Escape dots in CSS selectors (#element.incident.number -> #element\.incident\.number)
  const fieldWrapper = await SNTools.waitFor('#element\\.incident\\.number .form-field-addons');

  // Inject CSS into the iframe's document if it's framed inside gsft_main
  const targetDoc = fieldWrapper.ownerDocument;
  if (PLUGIN_CSS && !targetDoc.getElementById(`style-${PLUGIN_ID}`)) {
    const style = targetDoc.createElement('style');
    style.id = `style-${PLUGIN_ID}`;
    style.textContent = PLUGIN_CSS;
    targetDoc.head.appendChild(style);
  }

  if (fieldWrapper.querySelector('#my-copy-btn')) return;

  // Make the form-field row display inline-flex so the button sits neatly to the right
  fieldWrapper.style.display = 'flex';
  fieldWrapper.style.alignItems = 'center';
  fieldWrapper.style.gap = '6px';

  const btn = targetDoc.createElement('button');
  btn.id = 'my-copy-btn';
  btn.type = 'button'; // IMPORTANT: Prevents clicking the button from submitting the UI16 form!
  btn.className = 'btn btn-default';
  btn.textContent = 'Copy SysID';

  btn.onclick = () => {
    navigator.clipboard.writeText(record.sysId);
    btn.textContent = 'Copied!';
    setTimeout(() => {
      btn.textContent = 'Copy SysID';
    }, 1500);
  };

  fieldWrapper.appendChild(btn);
});
